#!/usr/bin/env python3
"""Render the complete measured kernel pass, including remaining gaps."""
import csv,html,json,math,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
E=ROOT/'docs/evidence/kernel-optimization'
def gm(xs):return math.exp(sum(math.log(x) for x in xs)/len(xs))
def main():
 d=json.loads((E/'results.json').read_text());rs=d['records'];meta=d['metadata'];summary=json.loads((E/'summary.json').read_text())
 assert len(rs)==92 and all(r['correctness']['before']['sha256']==r['correctness']['after']['sha256'] for r in rs)
 decode=[r for r in rs if r['group']=='main' and r['mode'] in ['native','scan','rgba','crop']]
 find=lambda name,mode:next(r for r in rs if r['group']=='main' and r['case']['name']==name and r['mode']==mode)
 selected=[find(n,m) for n,m in [('original-lzw-single-strip.tiff','rgba'),('lab-deflate','rgba'),('cmyk-deflate','rgba'),('noise-lzw','native'),('fax-g3','native'),('rgb-deflate','native'),('float32-deflate-p3','native'),('lerc-float-plain','native'),('webp-lossless','native'),('webp-lossy','native'),('jpeg-texture','native'),('rgb-none','rgba')]]
 aggregate=[]
 for mode in ['native','scan','rgba','crop']:
  group=[r for r in decode if r['mode']==mode]
  aggregate.append([mode,str(len(group)),f"{gm([r['statistics']['before']['median_ms']/r['statistics']['libtiff']['median_ms'] for r in group]):.2f}×",f"{gm([r['vs_libtiff'] for r in group]):.2f}×",f"{gm([r['speedup'] for r in group]):.2f}×"])
 lead=f"Across the {len(decode)} main decode workloads, the geometric-mean speedup is {gm([r['speedup'] for r in decode]):.2f}×. The new reader takes {gm([r['vs_libtiff'] for r in decode]):.2f}× as long as libtiff 4.7.1, down from {gm([r['statistics']['before']['median_ms']/r['statistics']['libtiff']['median_ms'] for r in decode]):.2f}× for the rebuilt previous reader."
 changes=[
  'Packed grayscale and palette RGBA: expand a source byte through a fixed lookup table, retaining partial-byte crops, both fill orders, orientation and output padding. The fixed table occupies 8 KiB. This removes generic sample extraction and per-pixel scaling from the common loop.',
  'Lab and CMYK: build the exact existing 1,501-entry Lab gamma table once per RGBA request; read contiguous 8/16-bit samples directly; admit full private segment staging for complete color reads. Separate-plane and raw YCbCr behavior remains unchanged.',
  'LZW: specialize/in-line bit and dictionary operations, and decode complete native segments once into private storage before checking exact endings. Optional complete RGBA staging uses the existing 1 MiB cap and cumulative/single allocation admission. Partial reads retain full validation and bounded replay.',
  'Deflate: group consecutive match emissions, avoiding state-machine dispatch per copied byte. Every emitted byte still updates the verified history and checksum, charges the same two work units and obeys output/input boundaries.',
  'Fax and Predictor 3: borrow fixed fax codebooks instead of returning array values, specialize scalar bit operations, and replace repeated predictor row division with proved incremental coordinates. Common single-channel sample widths specialize once per call.',
  'WebP: calculate VP8 filter decisions and corrections once per edge window; use an exact DC-only transform shortcut; dispatch common VP8L predictors once per pixel and traverse incremental coordinates with power-of-two tile shifts. Scalar color helpers are inlined.',
  'LERC: split wide rounding through 64-bit words and narrow normal float32 values directly, proving both against the original software IEEE model. Subnormals and exceptional values retain the original path. No native floating-point codec shortcut is used.'
 ]
 remaining='JPEG entropy decoding and validation/replay remain a substantial gap. A buffered-prefix experiment showed no measurable gain and was removed; this pass retains only small scalar inlining/power changes. Fax still traverses code trees and repacks expanded pixels; WebP remains scalar; LERC still performs software IEEE reconstruction. Partial compressed reads still validate the complete strip before returning pixels. This pass improves the measured kernels without claiming parity with libtiff or eliminating all bottlenecks.'
 scope='Core shortcuts refine the existing acceptance, numerical, output, frame and conservative-work models. No proof bypass, unsafe core code or runtime native codec dependency was added. Packed RGBA/Lab tables, color loads, staging admission, input-window continuity and the final caller-buffer commit remain tested ordinary Rust/C outside the formal core boundary. Existing whole-image acceptance profiles are unchanged.'
 tests=f"The complete crate passed {summary['proof']['verified']:,} obligations with zero errors and all {summary['negative_gates']} negative gates. {summary['rust_tests']} Rust tests, {summary['core_python_tests']} core Python methods and {summary['c_tests']} C methods passed, as did the complete C ASan/UBSan suite, all 31 original corpus images, 20,000 deterministic core mutations and the independent oracle's own 108 tests. C sanitizers do not instrument Rust; LeakSanitizer is disabled."
 correctness='All 92 before/after outputs match byte-for-byte, including JPEG. Against libtiff, 90 match exactly; the two textured-JPEG cases retain a maximum difference of one channel value. New tests cover all 65,536 legal VP8 DC values for both transforms, AC impulses, LERC ties/carries and exponent boundaries, packed byte values/crops/fill orders, and single-channel floating predictors. Existing stream tests compare exact work and bytes against scalar transitions across window, output, overlap, ring-wrap and failure boundaries.'
 crop='Nonzero-column packed and 16-bit crops use independent expected pixels: pinned libtiff 4.7.1 applies col_offset*samplesperpixel to a byte buffer in gtStripContig, which does not represent those sample offsets. Both the previous and current adapter preserve the independently expected result.'
 method=f"Measured {meta['utc']} on {meta['cpu_model']}, pinned CPU {meta['cpu']}; {meta['rounds']} randomized serial batches of at least {meta['milliseconds']:g} ms per engine/workload, plus three separate file-backed RSS processes. The unchanged C consumer opens a fresh handle per operation. Memory-callback timing excludes file loading, output allocation, hashing and startup. The exact previous source, current reader and pinned libtiff 4.7.1 were rebuilt. The reference uses zlib, not libdeflate, and its JPEG build has SIMD disabled. WebP uses the reference build's enabled CPU routines. Main decode geometric means exclude metadata, first-row, strip-height and default-strip-chopping diagnostics. These are host- and workload-specific measurements."
 reg=[r for r in rs if r['speedup']<1/1.1]
 regression='No main-run median slowdown exceeded 10%.' if not reg else 'Every median slowdown above 10% was retained and rechecked using nine randomized 500 ms batches per engine.'
 if reg:
  checks=json.loads((E/'recheck.json').read_text())['records'];assert len(checks)==len(reg)
  persistent=[r for r in checks if r['speedup']<1/1.1]
  regression+=' '+('None remained above 10%.' if not persistent else 'Persistent slowdowns: '+', '.join(f"{r['case']}/{r['mode']} ({r['group']}): {1/r['speedup']:.2f}×" for r in persistent)+'.')
 def values(r):
  s=r['statistics'];return [r['case']['label']+' / '+r['mode'],*[f"{s[e]['median_ms']:.4f}" for e in ['before','after','libtiff']],f"{r['speedup']:.2f}×",f"{r['vs_libtiff']:.2f}×"]
 headers=['Input / operation','Before ms','After ms','4.7.1 ms','Speedup','After / 4.7.1']
 def table(h,rows):return '| '+' | '.join(h)+' |\n| '+' | '.join(['---']*len(h))+' |\n'+''.join('| '+' | '.join(row)+' |\n' for row in rows)
 def htable(h,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
 repro='Reproduce with benchmarks/prepare-kernel-baseline.py, the full proof/test gates, benchmarks/prepare-reader.py, benchmarks/build-reader.sh and benchmarks/kernel-optimization.py. Run benchmarks/kernel-optimization-recheck.py for all >10% median slowdowns. The reverse patch restores the exact prior core/C source hashes. Full logs, source/binary/proof hashes, raw timings, correctness hashes and results.csv are archived in docs/evidence/kernel-optimization/.'
 md='# Codec and conversion kernel optimization\n\n'+lead+'\n\n'+table(headers,[values(r) for r in selected])+'\n## Main decode geometric means\n\n'+table(['Operation','Cases','Before / 4.7.1','After / 4.7.1','Speedup'],aggregate)+'\n'+regression+'\n\n## Changes\n\n'+'\n\n'.join(changes)+'\n\n## Remaining gaps and proof boundary\n\n'+remaining+'\n\n'+scope+'\n\n## Validation\n\n'+tests+'\n\n'+correctness+'\n\n'+crop+'\n\n## Measurement and reproduction\n\n'+method+'\n\n'+repro+'\n'
 (ROOT/'docs/kernel-optimization.md').write_text(md)
 with (E/'results.csv').open('w') as f:
  w=csv.writer(f);w.writerow(['group','case','mode','before_ms','after_ms','libtiff_ms','speedup','after_over_libtiff','before_rss_mib','after_rss_mib','libtiff_rss_mib'])
  for r in rs:
   s=r['statistics'];w.writerow([r['group'],r['case']['name'],r['mode'],*[s[e]['median_ms'] for e in ['before','after','libtiff']],r['speedup'],r['vs_libtiff'],*[s[e]['median_rss_mib'] for e in ['before','after','libtiff']]])
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TIFF kernel optimization</title><style>body{background:#f5f6f8;color:#172330;font:16px/1.6 system-ui;margin:0}main{max-width:1160px;margin:auto;padding:48px 24px}h1{font-size:38px;line-height:1.2}h2{margin-top:36px}.lead{font-size:21px}.scroll{overflow:auto;border:1px solid #d8e0e6;border-radius:8px;background:white}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:10px 14px;text-align:right;white-space:nowrap;border-bottom:1px solid #e7ebee}td:first-child,th:first-child{text-align:left}th{background:#eaf0f4}select,input{padding:9px 12px;font:inherit;margin:0 8px 14px 0}.note{font-size:14px;color:#4d6170}li{margin:12px 0}.good{border-left:4px solid #25876e;padding:12px 20px;background:#e8f4ef}@media print{body{background:white}main{padding:0}input,select{display:none}}</style><main><p class="note">verified-tiff · measured optimization</p><h1>Faster codec and conversion kernels</h1>'''
 page+='<p class="lead">'+html.escape(lead)+'</p><p class="good">'+html.escape(correctness)+'</p><h2>Selected results</h2><p class="note">Median milliseconds. Speedup is before / after; After / 4.7.1 above one means slower.</p>'+htable(headers,[values(r) for r in selected])
 page+='<h2>Main decode geometric means</h2>'+htable(['Operation','Cases','Before / 4.7.1','After / 4.7.1','Speedup'],aggregate)+'<p>'+html.escape(regression)+'</p><h2>What changed</h2><ol>'+''.join('<li>'+html.escape(x)+'</li>' for x in changes)+'</ol><h2>Remaining gaps</h2><p>'+html.escape(remaining)+'</p><h2>Verification and validation</h2><p>'+html.escape(scope)+'</p><p>'+html.escape(tests)+'</p><p>'+html.escape(crop)+'</p>'
 page+='<h2>All 92 workloads</h2><label>Group <select id="group"><option value="">All</option><option>main</option><option>layout</option><option>defaults</option></select></label><label>Filter <input id="query" placeholder="e.g. rgba, deflate, crop"></label><div id="all">'+htable(['Group']+headers,[[r['group']]+values(r) for r in rs])+'</div><h2>Measurement</h2><p>'+html.escape(method)+'</p><p class="note">'+html.escape(repro)+'</p></main>'
 page+='''<script>const group=document.getElementById('group'),query=document.getElementById('query');function filter(){for(const row of document.querySelectorAll('#all tbody tr'))row.hidden=!!((group.value&&row.cells[0].textContent!==group.value)||!row.textContent.toLowerCase().includes(query.value.toLowerCase()));}group.addEventListener('change',filter);query.addEventListener('input',filter);</script></html>'''
 target=ROOT.parent/'output/kernel-optimization.html';target.parent.mkdir(exist_ok=True);target.write_text(page)
 print(lead);print(regression);print(target)
if __name__=='__main__':main()
